    ) -> None:
        """A → B → C: A inherits ONLY B's fields, not C's (spec §1.6, btxdoc)."""
        bib = """
    @misc{a, title = "A", crossref = "b"}
    @misc{b, year = "2020", crossref = "c"}
    @misc{c, publisher = "GRANDPA"}
    """
        bbl, _ = run_bibtex(
            submission_command,
